<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Aluno');
$id_aluno=$_SESSION['id_usuario'];$id_questionario=intval($_GET['id']??$_POST['id']??0);if($id_questionario<=0){header('Location: questionarios_aluno.php');exit();}$mensagem='';
$stmt=$conexao->prepare('SELECT q.id_questionario,q.titulo,q.descricao FROM questionario q WHERE q.id_questionario=?');$stmt->bind_param('i',$id_questionario);$stmt->execute();$questionario=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$questionario){header('Location: questionarios_aluno.php');exit();}
$perguntas=[];$stmt=$conexao->prepare('SELECT id_pergunta,enunciado FROM pergunta WHERE id_questionario=? ORDER BY id_pergunta');$stmt->bind_param('i',$id_questionario);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$perguntas[]=$row;}$stmt->close();$ids=array_column($perguntas,'id_pergunta');$alternativas=[];if($ids){$placeholders=implode(',',array_fill(0,count($ids),'?'));$tipos=str_repeat('i',count($ids));$stmt=$conexao->prepare("SELECT id_pergunta,texto FROM alternativa WHERE id_pergunta IN ($placeholders) ORDER BY id_alternativa");$stmt->bind_param($tipos,...$ids);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$alternativas[$row['id_pergunta']][]=$row['texto'];}$stmt->close();}
$respondido=false;$respostas=[];$stmt=$conexao->prepare('SELECT r.id_pergunta,r.resposta FROM resposta r JOIN pergunta p ON p.id_pergunta=r.id_pergunta WHERE p.id_questionario=? AND r.id_usuario=?');$stmt->bind_param('ii',$id_questionario,$id_aluno);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$respondido=true;$respostas[$row['id_pergunta']]=$row['resposta'];}$stmt->close();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['enviar'])&&!$respondido){$enviadas=$_POST['resposta']??[];$validas=[];foreach($perguntas as $pergunta){$id_pergunta=(int)$pergunta['id_pergunta'];$valor=trim($enviadas[$id_pergunta]??'');if($valor===''){$mensagem='<div class="erro">Responda todas as perguntas antes de enviar.</div>';break;}if(!empty($alternativas[$id_pergunta])&&!in_array($valor,$alternativas[$id_pergunta],true)){$mensagem='<div class="erro">Uma das respostas selecionadas não é válida.</div>';break;}$validas[$id_pergunta]=$valor;}if(!$mensagem&&$validas){$conexao->begin_transaction();$ok=true;$stmt=$conexao->prepare('SELECT COUNT(*) AS total FROM resposta r JOIN pergunta p ON p.id_pergunta=r.id_pergunta WHERE p.id_questionario=? AND r.id_usuario=?');$stmt->bind_param('ii',$id_questionario,$id_aluno);$stmt->execute();$duplicado=(int)$stmt->get_result()->fetch_assoc()['total']>0;$stmt->close();if($duplicado){$ok=false;$mensagem='<div class="aviso">Este questionário já foi respondido.</div>';}else{$insert=$conexao->prepare('INSERT INTO resposta (id_pergunta,id_usuario,resposta) VALUES (?,?,?)');foreach($validas as $id_pergunta=>$valor){$insert->bind_param('iis',$id_pergunta,$id_aluno,$valor);if(!$insert->execute()){$ok=false;break;}}$insert->close();if($ok){$conexao->commit();$respondido=true;$respostas=$validas;$mensagem='<div class="sucesso">Questionário enviado com sucesso.</div>';}else{$conexao->rollback();$mensagem='<div class="erro">Não foi possível enviar o questionário.</div>';}}}}
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Aluno | Questionário</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fb;color:#1f2937}main{max-width:1000px;margin:32px auto;padding:0 20px 40px}.header{background:linear-gradient(135deg,#1f3b65,#4568a8);color:#fff;border-radius:18px;padding:26px 28px;margin-bottom:24px}.header h1{margin:0;font-size:2rem}.panel{background:#fff;border:1px solid #e2eaf5;border-radius:18px;padding:22px;margin-bottom:20px;box-shadow:0 8px 20px rgba(15,23,42,.04)}.pergunta{padding:16px 0;border-bottom:1px solid #edf2f9}.pergunta:last-child{border-bottom:0}.pergunta h3{margin:0 0 10px;color:#123d70}.opcao{display:block;margin:8px 0;color:#4b5a6e}.opcao input{margin-right:8px}.texto{width:100%;padding:10px;border:1px solid #dfe8f4;border-radius:8px;background:#f9fbff}.btn,.voltar{display:inline-block;border:0;border-radius:9px;padding:11px 16px;font-weight:bold;text-decoration:none;cursor:pointer}.btn{background:#0d4a8f;color:#fff}.voltar{background:#eaf3ff;color:#0b447d}.sucesso,.erro,.aviso{padding:10px 12px;border-radius:8px;margin-bottom:15px}.sucesso{background:#eaf7ee;color:#1d6f3b}.erro{background:#fee;color:#9d1c1c}.aviso{background:#fff4e5;color:#8a5a00}.bloqueado{background:#edf5ff;color:#17477c;padding:10px;border-radius:8px;margin-bottom:15px}</style></head><body><?php include '../../includes/menu_aluno.php';?><main><section class="header"><h1><?php echo htmlspecialchars($questionario['titulo']);?></h1><p><?php echo htmlspecialchars($questionario['descricao']??'');?></p></section><?php echo $mensagem;?><?php if($respondido):?><div class="bloqueado">Este questionário já foi respondido. As respostas estão disponíveis somente para consulta.</div><?php endif;?><section class="panel"><form method="POST"><input type="hidden" name="id" value="<?php echo $id_questionario;?>"><?php foreach($perguntas as $pergunta):$id_pergunta=(int)$pergunta['id_pergunta'];?><div class="pergunta"><h3><?php echo htmlspecialchars($pergunta['enunciado']);?></h3><?php if(!empty($alternativas[$id_pergunta])):foreach($alternativas[$id_pergunta] as $opcao):?><label class="opcao"><input type="radio" name="resposta[<?php echo $id_pergunta;?>]" value="<?php echo htmlspecialchars($opcao);?>" <?php echo (($respostas[$id_pergunta]??'')===$opcao)?'checked':'';?> <?php echo $respondido?'disabled':'';?>><?php echo htmlspecialchars($opcao);?></label><?php endforeach;else:?><textarea class="texto" name="resposta[<?php echo $id_pergunta;?>]" rows="3" <?php echo $respondido?'disabled':'';?>><?php echo htmlspecialchars($respostas[$id_pergunta]??'');?></textarea><?php endif;?></div><?php endforeach;?><?php if(!$perguntas):?><p>Nenhuma pergunta disponível.</p><?php elseif(!$respondido):?><button class="btn" name="enviar" value="1" type="submit">Enviar respostas</button><?php endif;?> <a class="voltar" href="questionarios_aluno.php">Voltar</a></form></section></main></body></html>
